package api_test

import (
	"net/http"
	"reflect"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// otherOrgInvoice creates an invoice for one of org's customers, through the API.
func otherOrgInvoice(t *testing.T, e *apitest.Env, org apitest.Org, customerID string) store.Invoice {
	t.Helper()
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{"customer_id": customerID, "currency": "USD",
		"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 1000}}}, &inv)
	return inv
}

// A request that names another organization's object must answer exactly as the same request naming an ID that does not
// exist. tmpl has one "%s" for the ID.
func TestOtherOrgIDsAnswerLikeUnknownIDs(t *testing.T) {
	e := apitest.New(t)
	gc := e.CreateCustomer(e.Globex, "Gina", "gina@globex.example")
	gInv := otherOrgInvoice(t, e, e.Globex, gc.ID)
	p := e.CreatePlan(e.Globex, "Business", "USD", "20.00")
	var gSub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Globex.Key, map[string]any{"customer_id": gc.ID, "plan_id": p.ID}, &gSub)
	var gEP store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/tally", "events": []string{"*"}}, &gEP)

	// same sends the request as Acme, once with Globex's ID and once with an ID that does not exist, and compares the answers.
	// body is called with the ID, so a body can name it.
	same := func(method, tmpl, globexID string, body func(id string) any) {
		t.Helper()
		unknown := e.Do(method, strings.Replace(tmpl, "%s", "999999", 1), e.Acme.Key, body("999999"))
		if unknown.Code != http.StatusNotFound || unknown.Map(t)["error"] != "not_found" {
			t.Fatalf("%s %s for an unknown ID: %s", method, tmpl, unknown)
		}
		got := e.Do(method, strings.Replace(tmpl, "%s", globexID, 1), e.Acme.Key, body(globexID))
		if got.Code != unknown.Code || !reflect.DeepEqual(got.Map(t), unknown.Map(t)) {
			t.Fatalf("%s %s with another organization's ID = %s, want the unknown-ID answer %s", method, tmpl, got, unknown)
		}
	}
	none := func(string) any { return nil }

	// The object in the path.
	same("GET", "/v1/invoices/%s/lines", gInv.ID, none)
	same("GET", "/v1/invoices/%s", gInv.ID, none)
	same("POST", "/v1/invoices/%s/void", gInv.ID, none)
	same("DELETE", "/v1/webhook-endpoints/%s", gEP.ID, none)
	if r := e.Do("GET", "/v1/webhook-endpoints/"+gEP.ID, e.Globex.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("the endpoint was deleted through another organization: %s", r)
	}

	// The customer named in a body. The subscription's first invoice must not be created for another organization either.
	same("POST", "/v1/invoices", gc.ID, func(id string) any {
		return map[string]any{"customer_id": id, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1}}}
	})
	same("POST", "/v1/subscriptions", gc.ID, func(id string) any { return map[string]any{"customer_id": id, "plan_id": p.ID} })

	// Nothing was created in Acme's name, and Globex's data is unchanged.
	var subs struct{ Items []store.Subscription }
	e.MustDo(http.StatusOK, "GET", "/v1/subscriptions", e.Acme.Key, nil, &subs)
	if len(subs.Items) != 0 {
		t.Fatalf("Acme has subscriptions %+v", subs.Items)
	}
	var invs struct{ Items []store.Invoice }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices", e.Acme.Key, nil, &invs)
	if len(invs.Items) != 0 {
		t.Fatalf("Acme has invoices %+v", invs.Items)
	}
	var gl struct{ Items []store.Invoice }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices", e.Globex.Key, nil, &gl)
	if len(gl.Items) != 1 || gl.Items[0].Status != store.InvoiceOpen {
		t.Fatalf("Globex's invoices changed: %+v", gl.Items)
	}
	if r := e.Do("GET", "/v1/subscriptions/"+gSub.ID, e.Globex.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("Globex's subscription: %s", r)
	}
}

// A lookup by email finds only the caller's organization's customers, and two organizations may share an address.
func TestCustomerEmailLookupIsPerOrganization(t *testing.T) {
	e := apitest.New(t)
	find := func(org apitest.Org, email string) []store.Customer {
		t.Helper()
		var out struct{ Items []store.Customer }
		e.MustDo(http.StatusOK, "GET", "/v1/customers?email="+email, org.Key, nil, &out)
		return out.Items
	}

	// Only Globex has this address.
	e.CreateCustomer(e.Globex, "Gina", "gina@example.com")
	if got := find(e.Acme, "gina@example.com"); len(got) != 0 {
		t.Fatalf("Acme found Globex's customer by email: %+v", got)
	}

	// Both organizations have this address: each finds its own, also after the other one was created later.
	ac := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	gc := e.CreateCustomer(e.Globex, "Jane", "jane@example.com")
	if got := find(e.Acme, "jane@example.com"); len(got) != 1 || got[0].ID != ac.ID {
		t.Fatalf("Acme's lookup = %+v, want %s", got, ac.ID)
	}
	if got := find(e.Globex, "jane@example.com"); len(got) != 1 || got[0].ID != gc.ID {
		t.Fatalf("Globex's lookup = %+v, want %s", got, gc.ID)
	}

	// Acme changes its address to one Globex has: Globex's lookup still finds Globex's customer.
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+ac.ID, e.Acme.Key, map[string]string{"email": "gina@example.com"}, nil)
	if got := find(e.Globex, "gina@example.com"); len(got) != 1 || got[0].Name != "Gina" {
		t.Fatalf("Globex's lookup after Acme's update = %+v", got)
	}
	if got := find(e.Acme, "gina@example.com"); len(got) != 1 || got[0].ID != ac.ID {
		t.Fatalf("Acme's lookup after its update = %+v", got)
	}

	// Acme deletes its customer: Globex's customer with the same old address is unaffected.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+ac.ID, e.Acme.Key, nil, nil)
	if got := find(e.Globex, "jane@example.com"); len(got) != 1 || got[0].ID != gc.ID {
		t.Fatalf("Globex's lookup after Acme's delete = %+v", got)
	}
}

