import re
p="internal/api/isolation_test.go"
src=open(p).read()
start=src.index("// A request for an object of another organization")
end=src.index("	// Nothing was created in Acme's name")
new='''// A request for an object of another organization must answer exactly as the same request for an ID that does not exist.
func TestOtherOrgIDsAnswerLikeUnknownIDs(t *testing.T) {
	e := apitest.New(t)
	gc := e.CreateCustomer(e.Globex, "Gina", "gina@globex.example")
	gInv := otherOrgInvoice(t, e, e.Globex, gc.ID)
	p := e.CreatePlan(e.Globex, "Business", "USD", "20.00")
	var gSub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Globex.Key, map[string]any{"customer_id": gc.ID, "plan_id": p.ID}, &gSub)
	var gEP store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/tally", "events": []string{"*"}}, &gEP)

	// same sends the request for Globex's object and for an unknown ID, as Acme, and compares the answers.
	same := func(method, tmpl, globexID string, body func(id string) any) {
		t.Helper()
		unknown := e.Do(method, replaceID(tmpl, "999999"), e.Acme.Key, body("999999"))
		if unknown.Code != http.StatusNotFound || unknown.Map(t)["error"] != "not_found" {
			t.Fatalf("%s for an unknown ID: %s", method, unknown)
		}
		got := e.Do(method, replaceID(tmpl, globexID), e.Acme.Key, body(globexID))
		if got.Code != unknown.Code || !reflect.DeepEqual(got.Map(t), unknown.Map(t)) {
			t.Fatalf("%s %s with another organization's ID = %s, want the unknown-ID answer %s", method, tmpl, got, unknown)
		}
	}
	none := func(string) any { return nil }

	// The object in the path.
	same("GET", "/v1/invoices/%s/lines", gInv.ID, none)
	same("GET", "/v1/invoices/%s", gInv.ID, none)
	same("POST", "/v1/invoices/%s/void", gInv.ID, none)
	same("DELETE", "/v1/webhook-endpoints/%s", gEP.ID, none)
	if r := e.Do("GET", "/v1/webhook-endpoints/"+gEP.ID, e.Globex.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("the endpoint was deleted through another organization: %s", r)
	}

	// The customer named in a body.
	invoiceBody := func(customerID string) any {
		return map[string]any{"customer_id": customerID, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1}}}
	}
	same("POST", "/v1/invoices", gc.ID, func(_ string) any { return invoiceBody(gc.ID) })
	same("POST", "/v1/subscriptions", gc.ID, func(_ string) any { return map[string]any{"customer_id": gc.ID, "plan_id": p.ID} })

'''
src=src[:start]+new+src[end:]
src=src.replace('''// otherOrgInvoice creates''','''// replaceID puts id in the place of the "%s" in tmpl.
func replaceID(tmpl, id string) string { return strings.Replace(tmpl, "%s", id, 1) }

// otherOrgInvoice creates''')
