181	func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
182		now := s.clock.Now()
183		inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
184			switch inv.Status {
185			case store.InvoicePaid:
186				return payments.ErrAlreadyPaid
187			case store.InvoiceVoid:
188				return payments.ErrInvoiceVoid
189			}
190			inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
191			return nil
192		})
193		if err != nil {
194			s.payError(w, err)
195			return
196		}
197		s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
198		writeJSON(w, http.StatusOK, s.viewInvoice(inv))
199	}
