438	// makes them a member with the invite's role and gives them a first API key.
439	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
440		s.mu.Lock()
441		defer s.mu.Unlock()
442		var inv Invite
443		found := false
444		for _, i := range s.invites {
445			if i.Token == token && token != "" {
446				inv, found = i, true
447				break
448			}
449		}
450		if !found || inv.RevokedAt != nil {
451			return User{}, Member{}, APIKey{}, ErrNotFound
452		}
453		var u User
454		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
455			u = s.users[id]
456		} else {
457			name = strings.TrimSpace(name)
458			if name == "" {
459				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
460			}
461			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
462			s.users[u.ID] = u
463			s.usersByEmail[normEmail(u.Email)] = u.ID
464		}
465		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
466		if err != nil {
467			return User{}, Member{}, APIKey{}, err
468		}
469		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)

