15	func writeJSON(w http.ResponseWriter, status int, v any) {
16		w.Header().Set("Content-Type", "application/json")
17		w.WriteHeader(status)
18		_ = json.NewEncoder(w).Encode(v)
19	}
20	
21	// writeError answers {"error": code, "message": message}.
22	func writeError(w http.ResponseWriter, status int, code, message string) {
23		writeJSON(w, status, map[string]string{"error": code, "message": message})
24	}
25	
26	// decode reads a JSON body (at most 1 MiB) into v, or answers 400 and returns false.
27	func decode(w http.ResponseWriter, r *http.Request, v any) bool {
28		dec := json.NewDecoder(io.LimitReader(r.Body, 1<<20))
29		if err := dec.Decode(v); err != nil {
30			writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
31			return false
32		}
33		return true
34	}
35	
36	// storeError answers for an error from the store or a service.
37	func (s *Server) storeError(w http.ResponseWriter, err error) {
38		switch {
39		case errors.Is(err, store.ErrNotFound):
40			writeError(w, http.StatusNotFound, "not_found", "no such object")
41		case errors.Is(err, store.ErrEmailTaken):
42			writeError(w, http.StatusConflict, "email_taken", err.Error())
43		case errors.Is(err, store.ErrAlreadyMember):
44			writeError(w, http.StatusConflict, "already_member", err.Error())
45		case errors.Is(err, store.ErrConflict):
46			writeError(w, http.StatusConflict, "conflict", err.Error())
47		case errors.Is(err, store.ErrInvalid):
48			writeError(w, http.StatusUnprocessableEntity, "invalid", err.Error())
49		default:
50			s.log.Error("request failed", "err", err)
51			writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
52		}
53	}
54	
55	// list is the shape of every list response. NextCursor is set when there is another page.
56	type list struct {
57		Items      any    `json:"items"`
58		NextCursor string `json:"next_cursor,omitempty"`
59	}
60	
61	// page is a request for one page of a list: ?limit= (1 to 100, default 20) and ?cursor= (from the previous page).
62	type page struct {
63		limit int
64		after *cursor
65	}
66	
67	// cursor is where a page starts: after the item with this creation time and ID.
68	type cursor struct {
69		T  time.Time `json:"t"`
70		ID string    `json:"id"`
71	}
72	
73	func (c cursor) less(o cursor) bool {
74		if !c.T.Equal(o.T) {
75			return c.T.Before(o.T)
76		}
77		return c.ID < o.ID
78	}
79	
80	// parsePage reads ?limit and ?cursor, or answers 400 and returns false.
81	func parsePage(w http.ResponseWriter, r *http.Request) (page, bool) {
82		p := page{limit: 20}
83		if v := r.URL.Query().Get("limit"); v != "" {
84			n, err := strconv.Atoi(v)
85			if err != nil || n < 1 || n > 100 {
86				writeError(w, http.StatusBadRequest, "invalid_limit", "limit is a whole number from 1 to 100")
87				return page{}, false
88			}
89			p.limit = n
90		}
91		if v := r.URL.Query().Get("cursor"); v != "" {
92			b, err := base64.RawURLEncoding.DecodeString(v)
93			var c cursor
94			if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
95				writeError(w, http.StatusBadRequest, "invalid_cursor", "the cursor is not one this API gave out")
96				return page{}, false
97			}
98			p.after = &c
99		}
100		return p, true
101	}
102	
103	func encodeCursor(c cursor) string {
104		b, _ := json.Marshal(c)
105		return base64.RawURLEncoding.EncodeToString(b)
106	}
107	
108	// pageOf returns one page of items, which are sorted by key (creation time, then ID), and the cursor of the next page.
109	func pageOf[T any](items []T, key func(T) cursor, p page) ([]T, string) {
110		start := 0
111		if p.after != nil {
112			start = len(items)
113			for i, it := range items {
114				if p.after.less(key(it)) {
115					start = i
116					break
117				}
118			}
119		}
120		end := min(start+p.limit, len(items))
121		out := items[start:end]
122		next := ""
123		if end < len(items) && len(out) > 0 {
124			next = encodeCursor(key(out[len(out)-1]))
125		}
126		return out, next
127	}
